//! Conservative temporal grouping. Candidates are selected from actual OCR output;
//! no replacement characters or words are generated by this module.
use crate::{check, Segment};
use anyhow::{bail, Result};
use serde::{Deserialize, Serialize};
use std::{
    collections::VecDeque,
    path::{Path, PathBuf},
    sync::{atomic::AtomicBool, Arc},
};
use unicode_normalization::UnicodeNormalization;

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct TextVariant {
    pub text: String,
    pub observations: u32,
    pub frame: PathBuf,
    pub crop: PathBuf,
    pub elapsed_ms: f64,
    pub confidence: Option<f32>,
    #[serde(default)]
    pub edited: bool,
}
#[derive(Debug)]
pub struct MergeReport {
    pub segments: Vec<Segment>,
    pub merged: usize,
    pub uncertain: usize,
    pub missing_images: usize,
}
fn normalized(text: &str) -> String {
    // Ignore line wrapping, but retain spaces separating ASCII words.
    let chars: Vec<_> = text.nfc().collect();
    let mut result = String::new();
    for (i, &ch) in chars.iter().enumerate() {
        if ch.is_whitespace() {
            let left = chars[..i].iter().rev().find(|c| !c.is_whitespace());
            let right = chars[i + 1..].iter().find(|c| !c.is_whitespace());
            if left.is_some_and(|c| c.is_ascii_alphanumeric())
                && right.is_some_and(|c| c.is_ascii_alphanumeric())
                && !result.ends_with(' ')
            {
                result.push(' ');
            }
        } else {
            result.push(ch);
        }
    }
    result
}
fn distance(a: &str, b: &str) -> usize {
    let a: Vec<_> = a.chars().collect();
    let b: Vec<_> = b.chars().collect();
    let mut prev: Vec<_> = (0..=b.len()).collect();
    for (i, x) in a.iter().enumerate() {
        let mut next = vec![i + 1; b.len() + 1];
        for (j, y) in b.iter().enumerate() {
            next[j + 1] = (prev[j + 1] + 1)
                .min(next[j] + 1)
                .min(prev[j] + usize::from(x != y));
        }
        prev = next;
    }
    prev[b.len()]
}
fn boxes(text: &str) -> usize {
    text.chars()
        .filter(|c| matches!(c, '\u{fffd}' | '□' | 'ㅁ'))
        .count()
}
fn close_text(a: &str, b: &str) -> bool {
    let a = normalized(a);
    let b = normalized(b);
    let length = a.chars().count().max(b.chars().count());
    if a == b {
        return !a.is_empty();
    }
    let edits = distance(&a, &b);
    // Very short captions are too ambiguous to auto-correct by text similarity.
    let placeholder = boxes(&a) != boxes(&b) && length >= 6 && edits == 1;
    placeholder
        || length >= 13
            && edits <= if length >= 28 { 2 } else { 1 }
            && edits as f64 / length as f64 <= 0.08
}
fn adjacent(a: &Segment, b: &Segment) -> bool {
    if a.lane != b.lane {
        return false;
    }
    a.model == b.model && a.revision == b.revision && (a.end - b.start).abs() <= 0.002
}
fn transient(row: &Segment) -> bool {
    row.observations == 1 && row.end - row.start <= 1.5
}
fn variants(row: &Segment) -> Vec<TextVariant> {
    let mut result = if row.variants.is_empty() {
        vec![TextVariant {
            text: row.text.clone(),
            observations: row.observations.max(1),
            frame: row.frame.clone(),
            crop: row.crop.clone(),
            elapsed_ms: row.elapsed_ms,
            confidence: row.confidence,
            edited: row.edited,
        }]
    } else {
        row.variants.clone()
    };
    if row.edited {
        if let Some(candidate) = result.iter_mut().find(|v| v.text == row.text) {
            candidate.edited = true;
        } else {
            result.push(TextVariant {
                text: row.text.clone(),
                observations: 0,
                frame: row.frame.clone(),
                crop: row.crop.clone(),
                elapsed_ms: row.elapsed_ms,
                confidence: row.confidence,
                edited: true,
            });
        }
    }
    result
}
pub fn preserve_edit(row: &mut Segment, old_text: &str) {
    if row.variants.is_empty() {
        row.variants.push(TextVariant {
            text: old_text.into(),
            observations: row.observations.max(1),
            frame: row.frame.clone(),
            crop: row.crop.clone(),
            elapsed_ms: row.elapsed_ms,
            confidence: row.confidence,
            edited: false,
        });
    }
    row.edited = true;
}
fn combine(rows: &[Segment], kind: &str) -> Segment {
    let mut result = rows[0].clone();
    let mut candidates: Vec<TextVariant> = Vec::new();
    for row in rows {
        for candidate in variants(row) {
            if let Some(old) = candidates.iter_mut().find(|v| v.text == candidate.text) {
                old.observations = old.observations.saturating_add(candidate.observations);
                old.edited |= candidate.edited;
            } else {
                candidates.push(candidate);
            }
        }
    }
    // Most observed whole string wins. On ties prefer fewer literal box/replacement
    // characters, then keep the earliest candidate. This is not model confidence.
    let mut best = 0;
    for i in 1..candidates.len() {
        if candidates[i].edited && !candidates[best].edited
            || candidates[i].edited == candidates[best].edited
                && (candidates[i].observations > candidates[best].observations
                    || candidates[i].observations == candidates[best].observations
                        && boxes(&candidates[i].text) < boxes(&candidates[best].text))
        {
            best = i;
        }
    }
    let winner = &candidates[best];
    result.text = winner.text.clone();
    result.frame = winner.frame.clone();
    result.crop = winner.crop.clone();
    result.elapsed_ms = winner.elapsed_ms;
    result.confidence = winner.confidence;
    result.end = rows.last().unwrap().end;
    result.observations = rows
        .iter()
        .map(|r| r.observations)
        .fold(0, u32::saturating_add);
    result.review |= rows.iter().any(|r| r.review) || candidates.len() > 1;
    result.edited = rows.iter().any(|r| r.edited);
    result.variants = candidates;
    result.merge_kind = Some(kind.into());
    result
}

struct Mask {
    width: usize,
    height: usize,
    pixels: Vec<u8>,
    dilated: Vec<u8>,
    count: usize,
}
impl Mask {
    fn from_image(path: &Path) -> Option<Self> {
        let image = image::open(path).ok()?.thumbnail(1280, 512).to_rgb8();
        let (w, h) = (image.width() as usize, image.height() as usize);
        let mut seed = vec![0u8; w * h];
        for (i, p) in image.pixels().enumerate() {
            let high = p.0.iter().max().unwrap();
            let low = p.0.iter().min().unwrap();
            if *low >= 175 && high - low <= 60 {
                seed[i] = 1;
            }
        }
        let mut pixels = vec![0u8; w * h];
        // Large bright background objects (hands/clothes) are not text evidence.
        for start in 0..seed.len() {
            if seed[start] == 0 {
                continue;
            }
            seed[start] = 0;
            let mut todo = vec![start];
            let mut part = Vec::new();
            let (mut left, mut right, mut top, mut bottom) = (w, 0, h, 0);
            while let Some(i) = todo.pop() {
                part.push(i);
                let (x, y) = (i % w, i / w);
                left = left.min(x);
                right = right.max(x);
                top = top.min(y);
                bottom = bottom.max(y);
                for (dx, dy) in [(-1, 0), (1, 0), (0, -1), (0, 1)] {
                    let (nx, ny) = (x as i32 + dx, y as i32 + dy);
                    if nx >= 0 && ny >= 0 && (nx as usize) < w && (ny as usize) < h {
                        let j = ny as usize * w + nx as usize;
                        if seed[j] != 0 {
                            seed[j] = 0;
                            todo.push(j);
                        }
                    }
                }
            }
            if part.len() >= 3 && part.len() <= 1000 && right - left < 140 && bottom - top < 85 {
                for i in part {
                    pixels[i] = 1;
                }
            }
        }
        let count = pixels.iter().filter(|&&p| p != 0).count();
        if count < 80 {
            return None;
        }
        let mut dilated = pixels.clone();
        for y in 0..h {
            for x in 0..w {
                if pixels[y * w + x] != 0 {
                    for dy in -1..=1 {
                        for dx in -1..=1 {
                            let (nx, ny) = (x as i32 + dx, y as i32 + dy);
                            if nx >= 0 && ny >= 0 && (nx as usize) < w && (ny as usize) < h {
                                dilated[ny as usize * w + nx as usize] = 1;
                            }
                        }
                    }
                }
            }
        }
        Some(Self {
            width: w,
            height: h,
            pixels,
            dilated,
            count,
        })
    }
    fn compatible(&self, other: &Self) -> bool {
        if self.width != other.width || self.height != other.height {
            return false;
        }
        // Require strong support in both directions and reject a locally changed
        // character even when it occupies only a small fraction of the whole ROI.
        let (w, h) = (self.width, self.height);
        let cols = w.div_ceil(24);
        let mut tiles = vec![(0usize, 0usize); cols * h.div_ceil(24)];
        let mut missing = 0;
        for y in 0..h {
            for x in 0..w {
                let i = y * w + x;
                if self.pixels[i] != 0 {
                    let cell = y / 24 * cols + x / 24;
                    tiles[cell].0 += 1;
                    if other.dilated[i] == 0 {
                        tiles[cell].1 += 1;
                        missing += 1;
                    }
                }
            }
        }
        missing as f64 / self.count as f64 <= 0.04
            && tiles
                .iter()
                .all(|&(count, lost)| count < 12 || lost <= 4 || lost as f64 / count as f64 <= 0.12)
    }
}
#[derive(Default)]
struct VisualCache {
    entries: VecDeque<(PathBuf, Option<Arc<Mask>>)>,
    missing: usize,
}
impl VisualCache {
    fn get(&mut self, path: &Path) -> Option<Arc<Mask>> {
        if let Some(i) = self.entries.iter().position(|(p, _)| p == path) {
            let entry = self.entries.remove(i).unwrap();
            let result = entry.1.clone();
            self.entries.push_back(entry);
            return result;
        }
        let value = Mask::from_image(path).map(Arc::new);
        if value.is_none() {
            self.missing += 1;
        }
        self.entries.push_back((path.into(), value.clone()));
        if self.entries.len() > 8 {
            self.entries.pop_front();
        }
        value
    }
    fn same(&mut self, a: &Segment, b: &Segment) -> bool {
        match (self.get(&a.crop), self.get(&b.crop)) {
            (Some(a), Some(b)) => a.compatible(&b) && b.compatible(&a),
            _ => false,
        }
    }
}
/// Operates on results and their cached crop images; never invokes an OCR model.
pub fn merge_repeated_segments(input: &[Segment], cancel: &AtomicBool) -> Result<MergeReport> {
    check(cancel)?;
    crate::validate_segments(input)?;
    let mut report = MergeReport {
        segments: vec![],
        merged: 0,
        uncertain: 0,
        missing_images: 0,
    };
    for lane in [
        crate::SubtitleLane::Single,
        crate::SubtitleLane::Left,
        crate::SubtitleLane::Right,
    ] {
        let mut rows: Vec<_> = input.iter().filter(|r| r.lane == lane).cloned().collect();
        crate::sort_segments(&mut rows);
        let part = merge_lane(&rows, cancel)?;
        report.segments.extend(part.segments);
        report.merged += part.merged;
        report.uncertain += part.uncertain;
        report.missing_images += part.missing_images;
    }
    crate::sort_segments(&mut report.segments);
    Ok(report)
}
fn merge_lane(input: &[Segment], cancel: &AtomicBool) -> Result<MergeReport> {
    check(cancel)?;
    crate::validate_segments(input)?;
    let mut rows = input.to_vec();
    let before = rows.len();
    let mut visual = VisualCache::default();
    let mut i = 0;
    while i + 1 < rows.len() {
        check(cancel)?;
        if !adjacent(&rows[i], &rows[i + 1]) {
            i += 1;
            continue;
        }
        let a = normalized(&rows[i].text);
        let b = normalized(&rows[i + 1].text);
        if !a.is_empty() && a == b {
            let merged = combine(&rows[i..i + 2], "same_text");
            rows.splice(i..i + 2, [merged]);
            continue;
        }
        if rows[i].edited || rows[i + 1].edited {
            i += 1;
            continue;
        }
        // A -> one-frame OCR wobble -> A is stronger evidence than a fuzzy pair.
        if i + 2 < rows.len()
            && !rows[i + 2].edited
            && adjacent(&rows[i + 1], &rows[i + 2])
            && a == normalized(&rows[i + 2].text)
            && transient(&rows[i + 1])
            && close_text(&rows[i].text, &rows[i + 1].text)
            && visual.same(&rows[i], &rows[i + 1])
            && visual.same(&rows[i], &rows[i + 2])
        {
            let merged = combine(&rows[i..i + 3], "temporal_vote");
            rows.splice(i..i + 3, [merged]);
            continue;
        }
        let stable_pair = rows[i].observations >= 2 && transient(&rows[i + 1])
            || rows[i + 1].observations >= 2 && transient(&rows[i]);
        let box_pair =
            (boxes(&a) > 0) != (boxes(&b) > 0) && (transient(&rows[i]) || transient(&rows[i + 1]));
        if (stable_pair || box_pair) && close_text(&a, &b) && visual.same(&rows[i], &rows[i + 1]) {
            let merged = combine(&rows[i..i + 2], "visual_vote");
            rows.splice(i..i + 2, [merged]);
            continue;
        }
        i += 1;
    }
    let uncertain = rows.iter().filter(|r| r.variants.len() > 1).count();
    Ok(MergeReport {
        merged: before - rows.len(),
        segments: rows,
        uncertain,
        missing_images: visual.missing,
    })
}
/// Explicit user selection can resolve cases the conservative automatic pass leaves apart.
pub fn merge_selected_segments(input: &[Segment], selected: &[usize]) -> Result<Vec<Segment>> {
    crate::validate_segments(input)?;
    let mut selected = selected.to_vec();
    selected.sort_unstable();
    selected.dedup();
    if selected.len() < 2 {
        bail!("합칠 행을 두 개 이상 선택하세요.");
    }
    let first = selected[0];
    let last = *selected.last().unwrap();
    if last >= input.len() {
        bail!("선택한 행이 결과 범위를 벗어났습니다.");
    }
    let lane = input[first].lane;
    if selected.iter().any(|&i| input[i].lane != lane)
        || (first..=last).filter(|&i| input[i].lane == lane).count() != selected.len()
    {
        bail!("같은 영역에서 연속된 행만 합칠 수 있습니다. 좌우 영역은 서로 합치지 않습니다.");
    }
    let chosen: Vec<_> = selected.iter().map(|&i| input[i].clone()).collect();
    if !chosen.windows(2).all(|p| adjacent(&p[0], &p[1])) {
        bail!("시간이 연속이고 모델·버전이 같은 항목만 합칠 수 있습니다. 빈 시간 구간은 자동으로 메우지 않습니다.");
    }
    let merged = combine(&chosen, "user_selection");
    let mut rows: Vec<_> = input
        .iter()
        .enumerate()
        .filter(|(i, _)| !selected.contains(i))
        .map(|(_, r)| r.clone())
        .collect();
    rows.push(merged);
    crate::sort_segments(&mut rows);
    Ok(rows)
}
